-blonde-dood/","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p853231699"],"reference":"new-work-dossier-readings-019.json#335","checked_at":"2026-11-02T21:38:34.662Z","note":"1985novel version196pISBN9789029508483, explicitly distinguished from52p1982EenKleineBlondeDood precursor and later expanded217p versions. Publisher calls the work pseudo-autobiographical. Original short text makes no claims that fictional father/son events are verified author biography. Existing identity and dependencies checked separately before addition."},{"type":"original_substantive_source_review","sources":["https://www.singeluitgeverijen.nl/de-arbeiderspers/boek/de-kleine-blonde-dood/","https://www.bibliotheek.nl/catalogus/titel.343581817.html/de-kleine-blonde-dood/","https://www.boekenplatform.nl/de-kleine-blonde-dood-86022","https://www.dbnl.org/tekst/anbe001lexi01_01/lvlw00094.php?q=4","https://data.bibliotheken.nl/id/nbt/p853231699"],"review":"content-review-014.json"},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","cover_id":6275547,"sha256":"06adf9dca41a31640b975c0698c524f940c1e2bcc5ee962366046d0d5bfe14cd","reference":"cover-semantic-review-010.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T21:38:34.662Z","review_batch":"nl-scale-20261102-019"}},{"ref":"m5","relation":"catalog_edition_metadata","key":{"edition_id":"@e5"},"before":null,"after":{"edition_id":"@e5","work_id":"@w5","bound_author_id":"@a2","bound_title":"De kleine blonde dood","bound_language":"dut","bound_isbn13":"9789029508483","format":"paperback","cover_url":"https://covers.openlibrary.org/b/id/6275547-L.jpg?default=false","card_cover_url":"https://c